#!/usr/bin/env bash
# Reproducible Capacitor 7 iOS setup. Never starts an external build or upload.
set -euo pipefail

cd "$(dirname "$0")/.."

if [ ! -d ios/App/App.xcodeproj ]; then
  # Native project may be generated by Codemagic from a clean Git checkout.
  # A one-time GitHub Actions workflow also commits this scaffold.
  npm run build:native
  npx cap add ios
else
  npm run build:native
fi

npx cap sync ios

# Keep the generated Info.plist privacy descriptions and display name correct.
python3 - <<'PY'
import plistlib
from pathlib import Path
path = Path('ios/App/App/Info.plist')
with path.open('rb') as f:
    info = plistlib.load(f)
info['CFBundleDisplayName'] = 'JOMON pix'
info['NSPhotoLibraryUsageDescription'] = '写真を選択してJOMON pixで加工するために使用します。'
info['NSPhotoLibraryAddUsageDescription'] = '加工した写真を端末に保存するために使用します。'
info['UIFileSharingEnabled'] = True
info['LSSupportsOpeningDocumentsInPlace'] = True
info['ITSAppUsesNonExemptEncryption'] = False
with path.open('wb') as f:
    plistlib.dump(info, f)
PY

python3 scripts/generate-ios-icon.py

echo "Prepared Capacitor iOS workspace: ios/App/App.xcworkspace"
echo "Web asset base: / (native bundle), bundle ID: com.jomonpix.app"
